export interface Anchor {
  key: string;

  top: number;

  nr: number;

  scrollY: number;
}

const ROOT_SELECTOR = '#app-hoofd';

// Lazy bodies keep growing the page after the rerender, so one correction
// round is not enough.
const SETTLE_ROUNDS = 6;
const SETTLE_PAUSE_MS = 40;

const PENDING_MAX_MS = 4000;

function root(): HTMLElement | null {
  if (typeof document === 'undefined' || !document.querySelector) return null;
  return document.querySelector(ROOT_SELECTOR);
}

function nodesWith(root: HTMLElement, key: string): HTMLElement[] {
  return [...root.querySelectorAll<HTMLElement>('[data-iri], [data-open-key]')]
    .filter((n) => n.getAttribute('data-iri') === key
      || n.getAttribute('data-open-key') === key);
}

export function pinAnchor(): Anchor | null {
  const el = root();
  if (!el || typeof window === 'undefined') return null;
  const height = window.innerHeight || 0;
  const scrollY = typeof window.scrollY === 'number' ? window.scrollY : 0;
  let best: HTMLElement | null = null;
  let bestTop = 0;
  let bestKey = '';
  for (const n of el.querySelectorAll<HTMLElement>('[data-iri], [data-open-key]')) {
    const r = n.getBoundingClientRect();
    if (r.bottom <= 0 || r.top > height) continue;
    if (!best || Math.abs(r.top) < Math.abs(bestTop)) {
      best = n;
      bestTop = r.top;
      bestKey = n.getAttribute('data-iri') || n.getAttribute('data-open-key') || '';
    }
  }
  if (!best || !bestKey) return scrollY ? { key: '', top: 0, nr: 0, scrollY } : null;
  return {
    key: bestKey,
    top: bestTop,
    nr: Math.max(0, nodesWith(el, bestKey).indexOf(best)),
    scrollY,
  };
}

export async function restoreAnchor(anchor: Anchor | null): Promise<boolean> {
  if (!anchor || typeof window === 'undefined' || !window.scrollBy) return false;
  const el = root();
  let hit = false;
  if (el && anchor.key) {
    for (let i = 0; i < SETTLE_ROUNDS; i += 1) {

      const list = nodesWith(el, anchor.key);
      const node = list[Math.min(anchor.nr, list.length - 1)];
      if (!node) break;
      const delta = node.getBoundingClientRect().top - anchor.top;
      hit = true;
      if (Math.abs(delta) < 1) return true;
      window.scrollBy(0, delta);
      await new Promise((r) => setTimeout(r, SETTLE_PAUSE_MS));
    }
  }
  if (hit) return true;
  if (anchor.scrollY && window.scrollTo) {
    window.scrollTo(0, anchor.scrollY);
    return true;
  }
  return false;
}

let pending: Anchor | null = null;
let expiry: ReturnType<typeof setTimeout> | null = null;

export function holdAnchor(): void {
  if (pending) return;
  pending = pinAnchor();
  if (!pending) return;

  expiry = setTimeout(() => { void releaseAnchor(); }, PENDING_MAX_MS);
}

export function hasPendingAnchor(): boolean {
  return pending !== null;
}

export async function releaseAnchor(): Promise<boolean> {
  const a = pending;
  pending = null;
  if (expiry) { clearTimeout(expiry); expiry = null; }
  if (!a) return false;
  return restoreAnchor(a);
}

const SPOT_VALID_MS = 1200;
let spot: { y: number; t: number } | null = null;

function rememberSpot(): void {
  if (typeof window === 'undefined') return;
  spot = { y: window.scrollY || 0, t: Date.now() };
}

function forgetSpot(): void { spot = null; }

if (typeof document !== 'undefined' && document.addEventListener) {
  document.addEventListener('pointerdown', rememberSpot, true);
  document.addEventListener('keydown', (e) => {
    const k = (e as KeyboardEvent).key;
    if (k === 'Enter' || k === ' ' || k === 'Spacebar') rememberSpot();
  }, true);
  document.addEventListener('wheel', forgetSpot, true);
  document.addEventListener('touchmove', forgetSpot, true);
}

export function restoreReaderSpot(): boolean {
  const p = spot;
  spot = null;
  if (!p || typeof window === 'undefined' || !window.scrollTo) return false;
  if (Date.now() - p.t > SPOT_VALID_MS) return false;
  if (typeof document !== 'undefined') {
    const a = document.activeElement;
    if (a && a !== document.body && a !== document.documentElement) return false;
  }
  const now = typeof window.scrollY === 'number' ? window.scrollY : 0;
  if (Math.abs(now - p.y) < 2) return false;
  window.scrollTo(0, p.y);
  return true;
}
